import yaml, json
with open('/agent/workspace/openapi/derived/v1-legacy.yaml') as f:
    spec = yaml.safe_load(f)
for path, ops in spec['paths'].items():
    if path.startswith('/files'):
        for method, op in ops.items():
            rb = op.get('requestBody', {})
            print(path, method, op.get('operationId'), json.dumps(rb)[:400])
EOF
